<!-- /wp:wdl/custom-title-6 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#33302a"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#33302a;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">答えにくいものほど、はっきり書きました。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-qa-1 {"FontLabel":"Roboto","mainColor":"#8a6a2f"} -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">当日にキャンセルしたい</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">お電話ください。キャンセル料はいただいていません。ただしコース料理をご予約の場合は、材料を仕入れているため、前日18時を過ぎたお取り消しは<strong>1名につき2,200円</strong>をお願いしています。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">遅れそうです</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">お電話いただければ30分までお待ちします。それを過ぎるとお席を空けさせていただくことがあります。ご連絡なく20分お越しにならない場合も同じです。申し訳ありません。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">人数が減りました</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">当日でも構いません。お電話ください。コースの場合は前日18時までにお願いします。増える場合は、お席の都合で難しいことがあります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">なぜカードが使えないのですか</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">手数料のぶんを料理の値段に乗せたくないためです。電子マネー（交通系・PayPay）はお使いいただけます。近くにATMがありますので、必要でしたらご案内します。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">写真を撮ってもいいですか</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">お料理の写真はご自由に。他のお客さまが写らないようにだけお願いします。動画の撮影と、明るいライトの使用はご遠慮いただいています。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">子どもがうるさくしてしまいそう</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">気になさらないでください。泣いても走ってもかまいません。ほかのお客さまには、そういう店だとお伝えしています。離乳食のお持ち込みも大丈夫です（温めもいたします）。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">一人で入りにくいのですが</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">カウンターが4席あります。半分ほどはおひとりの方です。本を読んでいらっしゃる方も多いです。話しかけることはいたしません。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">苦手な食材があります</p></div><div class="open_icon" style="background:#8a6a2f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#8a6a2f">A<div style="background:#8a6a2f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">ご予約のときにお知らせください。コースは3日前まで、単品はその場で対応できることが多いです。「嫌い」でも「アレルギー」でも、同じように扱います。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
